"C:\\WINDOWS\\System32\\WindowsPowerShell\\v1.0\\powershell.exe" -Command '$releaseDir = "E:'"\\codex-LOOP\\deliveries\\codex-loop-github-open-source-20260820\\codex-loop-open-source\"
"'$sha256File = "$releaseDir'"\\SHA256SUMS\"
"'$lines = Get-Content $sha256File
$pass = 0; $fail = 0; $failures = @()
foreach ($line in $lines) {
    if ($line -match '"'"'^([a-f0-9]{64})'"\\s+(.+)"'$'"') {
        "'$expectedHash = $Matches[1]
        $relPath = $Matches[2] -replace '"'/', '\\'
        "'$fullPath = Join-Path $releaseDir $relPath
        if (Test-Path $fullPath) {
            $actualHash = (Get-FileHash $fullPath -Algorithm SHA256).Hash.ToLower()
            if ($actualHash -eq $expectedHash) { $pass++ }
            else { $fail++; $failures += "MISMATCH: $relPath expected=$expectedHash actual=$actualHash" }
        } else {
            $fail++; $failures += "MISSING: $relPath"
        }
    }
}
Write-Host "PASS: $pass  FAIL: $fail"
$failures | ForEach-Object { Write-Host $_ }'

