"C:\\WINDOWS\\System32\\WindowsPowerShell\\v1.0\\powershell.exe" -Command '# 224 managed entries but SHA256SUMS has 226.
# The test says: set(SHA256SUMS) == managed - {"SHA256SUMS"} and "SHA256SUMS" in managed
# But SHA256SUMS is NOT in managed_files_v2.txt (0 match above)!
# And SHA256SUMS itself has 226 entries. managed has 224.
# Let'"'s find what's in SHA256SUMS but not in managed_files_v2.txt
"'$releaseDir = "E:'"\\codex-LOOP\\deliveries\\codex-loop-github-open-source-20260820\\codex-loop-open-source\"
"'$managed = (Get-Content "$releaseDir'"\\config\\managed_files_v2.txt\" | Where-Object { "'$_ -notmatch '"'"'^'"\\s*#' -and "'$_ -match '"'\\S' }) | ForEach-Object { "'$_.Trim() }
$sha = (Get-Content "$releaseDir'"\\SHA256SUMS\") | ForEach-Object { ("'$_ -split '"'\\s+',2)[1] }

"'$inManagedNotSha = $managed | Where-Object { $sha -notcontains $_ }
$inShaNotManaged = $sha | Where-Object { $managed -notcontains $_ }
Write-Host "In managed but NOT in SHA256SUMS:"
$inManagedNotSha | ForEach-Object { Write-Host "  $_" }
Write-Host ""
Write-Host "In SHA256SUMS but NOT in managed:"
$inShaNotManaged | ForEach-Object { Write-Host "  $_" }'

